func (s *ObtainContentTagListService) FetchContentTagList(ctx context.Context, req *tv_data.FetchContentTagListRequest) ([]string, error) {
	if err := s.verifyParams(req); err != nil {
		return nil, err
	}

	logs.CtxPushNotice(ctx, "Req_Source", req.Source)
	logs.CtxPushNotice(ctx, "Req_ParentSource", req.ParentSource)
	// Load mother model information, determine if it is iptv injection
	parentSource, err := s.RetrieveParentSourceInfo(ctx, req.Source, req.ParentSource)
	if err != nil {
		logs.CtxError(ctx, "[RetrieveParentSourceInfo] err=%v", err)
		return nil, err
	}

	// ! The order of all tags here cannot change, otherwise it will affect the disaster recovery configuration
	tagList := make([]string, 0)
	// IPTV injected tag
	injectTag, err := s.FetchIPTVInjectTag(ctx, parentSource.CoopType, parentSource.NameEn)
	if err != nil {
		logs.CtxError(ctx, "[FetchIPTVInjectTag] err=%v", err)
		return nil, err
	} else if injectTag != "" {
		tagList = append(tagList, injectTag)
	}

	// SDK tags & SDK sub-category tags
	sdkTagList, err := s.RetrieveSDKTagList(ctx, parentSource.NameEn, req.Category)
	if err != nil {
		logs.CtxError(ctx, "[RetrieveSDKTagList] err=%v", err)
		return nil, err
	}
	logs.CtxInfo(ctx, "source=%v, pSource=%v, sdkTagList=%v", req.Source, req.ParentSource, sdkTagList)
	tagList = append(tagList, sdkTagList...)

	// Licensing tags
	licenseTag := toolsTag.BuildTvLicenseContentTag(parentSource.TvLicense.String())
	tagList = append(tagList, licenseTag)

	// Green model tags
	greenModelConf := s.tccClient.FetchTvSourceGreenConf(ctx)
	if greenModelConf != nil && (greenModelConf.AllGreenModelOpen || greenModelConf.OpenGreenModelSourceMap[parentSource.NameEn]) {
		if req.Source != "local_test" { // The online may have callers writing channels with local_test requests, so local_test does not enable green mode restrictions
			greenTag := toolsTag.BuildXSJPatternContentTag(tv_model.TagContentPattern_Green.String())
			tagList = append(tagList, greenTag)
		}
	}

	// Youth model tags
	if req.GetIsTeenagerModel() {
		teenagerTag := toolsTag.BuildXSJPatternContentTag(tv_model.TagContentPattern_Teenager.String())
		tagList = append(tagList, teenagerTag)
	}

	metricTags := map[string]string{
		"parent_source": parentSource.NameEn,
		"license":       parentSource.TvLicense.String(),
		"coop_type":     parentSource.CoopType.String(),
	}
	metrics.EmitCounter("content_tag.total", 1, metricTags)
	// In the BesTV IPTV scenario, return [coop]BesTV_IPTV tag
	if parentSource.GetTvLicense() == tv_model.TvLicense_BesTV && parentSource.GetCoopType() == tv_model.TvCoopType_IpTv {
	metrics.EmitCounter("content_tag.coop_tag", 1, metricTags)
		coopTag := toolsTag.BuildLicenseCoopTag(tv_model.LicenseCoopType_BesTV_IPTV.String())
		tagList = append(tagList, coopTag)
	}

	return tagList, nil
}

